#!/usr/bin/env bash
# Generate the meson cross file used by the autotools/meson dependencies
# (glib, pixman, libslirp).  QEMU generates its own cross file from its
# configure run.
#
#   scripts/gen-cross-file.sh <output-file>
set -euo pipefail

APP_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
# shellcheck source=/dev/null
source "$APP_ROOT/scripts/env.sh"

OUT=${1:-$BUILD/config-meson.cross}
mkdir -p "$(dirname "$OUT")"

cat > "$OUT" <<EOF
# Generated by scripts/gen-cross-file.sh - do not edit.
[binaries]
c = '$CC'
cpp = '$CXX'
ar = '$AR'
strip = '$STRIP'
ranlib = '$RANLIB'
pkg-config = '/usr/bin/pkg-config'

[properties]
pkg_config_libdir = '$PREFIX/lib/pkgconfig:$PREFIX/share/pkgconfig'
needs_exe_wrapper = true

[host_machine]
system = 'linux'
cpu_family = 'aarch64'
cpu = 'aarch64'
endian = 'little'

[built-in options]
c_args = ['-O3', '-fPIC', '-march=armv8-a+simd+crc+crypto', '-DANDROID', '-D__ANDROID__', '-D__LIMBO__', '-I$PREFIX/include']
cpp_args = ['-O3', '-fPIC', '-march=armv8-a+simd+crc+crypto', '-DANDROID', '-D__ANDROID__', '-D__LIMBO__', '-I$PREFIX/include']
c_link_args = ['-L$PREFIX/lib', '-Wl,-rpath-link,$PREFIX/lib']
c_std = 'gnu11'
EOF
echo "wrote $OUT"
